// FUNCTION: BFME2 0x0006DE3D size=324 name=?On_Frame_Update@W3DDynamicLight@@UAEXXZ evidence=N:ledger tier=B hypothesis:Z
void W3DDynamicLight::On_Frame_Update(void)
{
	if (!m_enabled)
		return;

	Real factor = 1.0f;
	if (m_curIncreaseFrameCount > 0 && m_increaseFrameCount > 0)
	{
		// increasing
		m_curIncreaseFrameCount--;
		factor = (m_increaseFrameCount - m_curIncreaseFrameCount) / (Real)m_increaseFrameCount;
	}
	else if (m_decayFrameCount == 0)
	{
		factor = 1.0f;	// never decays
	}
	else
	{
		m_curDecayFrameCount--;
		if (m_curDecayFrameCount == 0)
		{
			m_enabled = false;
			return;
		}
		factor = m_curDecayFrameCount / (Real)m_decayFrameCount;
	}

	if (m_decayRange)
	{
		FarAttenEnd = factor * m_targetRange;
		if (FarAttenEnd < FarAttenStart)
			FarAttenEnd = FarAttenStart;
	}
	if (m_decayColor)
	{
		Ambient = m_targetAmbient * factor;
		Diffuse = m_targetDiffuse * factor;
	}
}

// FUNCTION: BFME2 0x0006DF81 size=105 name=?setFrameFade@W3DDynamicLight@@QAEXII@Z evidence=N:ledger tier=B hypothesis:Z
